output_text:
[
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Shopping carts are forbidden in one-cell-wide aisles that are flanked by shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_push_cart_into_top_aisle",
    "text": "A shopper may not push a cart north from the mouth of a single-file top-shelf aisle.",
    "abstraction": {
      "state_properties": {
        "topAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "topAisleMouth",
          "hasCart",
          "N"
        ]
      }
    }
  },
  {
    "id": "park_then_fetch_from_top_aisle",
    "text": "If a shopper parks a cart at the mouth of a single-file top-shelf aisle, they are obliged to go into that aisle and perform the shelf interaction on foot.",
    "abstraction": {
      "state_properties": {
        "topAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "parkCartAtTopAisle": {
          "pre": {
            "and": [
              "topAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "topAisleShelfInteractionOnFoot": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtTopAisle",
      "discharge": "topAisleShelfInteractionOnFoot"
    }
  },
  {
    "id": "cartless_only_during_top_aisle_excursion",
    "text": "Walking without a cart is allowed only within the single-file top-shelf aisle and its cart-parking mouth.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "topAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "topAisleExcursionZone": {
          "or": [
            "singleFileShelfAisle",
            "topAisleMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "topAisleExcursionZone"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_top_aisle_pick",
    "text": "After interacting with an item in a single-file shelf aisle on foot, the shopper must return to the aisle mouth and take the cart again.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "topAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "topAislePickOnFoot": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": null
        },
        "retrieveCartAtMouth": {
          "pre": {
            "and": [
              "topAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "topAislePickOnFoot",
      "discharge": "retrieveCartAtMouth"
    }
  },
  {
    "id": "ordinary_shelf_interactions_require_cart",
    "text": "Interactions with ordinary shelf-facing cells outside the single-file top aisles must be done while holding the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "ordinaryShelfAccessCell": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "ordinaryShelfAccessCell",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "do_not_leave_cart_unretrieved",
    "text": "Whenever a shopper sets a cart down, they are obliged to pick it up again before leaving the store.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "setDownCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "pickUpCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "setDownCart",
      "discharge": "pickUpCart"
    }
  },
  {
    "id": "park_cart_only_in_wide_non_shelf_space",
    "text": "A cart may be set down only in a wide non-shelf-adjacent thoroughfare, not in a narrow aisle or beside a shelf.",
    "abstraction": {
      "state_properties": {
        "wideNonShelfThoroughfare": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "setDownCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "setDownCart",
          {
            "not": "wideNonShelfThoroughfare"
          }
        ]
      }
    }
  }
]
